const extendApplicationOperationStepLease = `-- name: ExtendApplicationOperationStepLease :execrows
UPDATE application_operation_step step SET lease_until=now()+interval '45 seconds'
WHERE step.id=$1 AND step.workspace_id=$2 AND step.runtime_id=$3 AND step.claim_token=$4 AND step.state='running'
 AND EXISTS(SELECT 1 FROM application_operation operation WHERE operation.id=step.operation_id AND operation.workspace_id=step.workspace_id AND operation.deadline_at>now())
`

type ExtendApplicationOperationStepLeaseParams struct {
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	RuntimeID   pgtype.UUID `json:"runtime_id"`
	ClaimToken  pgtype.UUID `json:"claim_token"`
}

func (q *Queries) ExtendApplicationOperationStepLease(ctx context.Context, arg ExtendApplicationOperationStepLeaseParams) (int64, error) {
	result, err := q.db.Exec(ctx, extendApplicationOperationStepLease,
		arg.ID,
		arg.WorkspaceID,
		arg.RuntimeID,
		arg.ClaimToken,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

