const getApplicationInstanceDependencies = `-- name: GetApplicationInstanceDependencies :many
SELECT id, workspace_id, application_id, runtime_id, daemon_id, revision, observed_revision, generation, desired_state, process_state, health_state, error, code_version, dirty, started_at, observed_at, metrics, created_at, updated_at, observed_generation FROM application_instance WHERE workspace_id=$1 AND id=ANY($2::uuid[])
`

type GetApplicationInstanceDependenciesParams struct {
	WorkspaceID pgtype.UUID   `json:"workspace_id"`
	Ids         []pgtype.UUID `json:"ids"`
}

func (q *Queries) GetApplicationInstanceDependencies(ctx context.Context, arg GetApplicationInstanceDependenciesParams) ([]ApplicationInstance, error) {
	rows, err := q.db.Query(ctx, getApplicationInstanceDependencies, arg.WorkspaceID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ApplicationInstance{}
	for rows.Next() {
		var i ApplicationInstance
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ApplicationID,
			&i.RuntimeID,
			&i.DaemonID,
			&i.Revision,
			&i.ObservedRevision,
			&i.Generation,
			&i.DesiredState,
			&i.ProcessState,
			&i.HealthState,
			&i.Error,
			&i.CodeVersion,
			&i.Dirty,
			&i.StartedAt,
			&i.ObservedAt,
			&i.Metrics,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ObservedGeneration,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

