const listApplicationDeletionBlockers = `-- name: ListApplicationDeletionBlockers :many
SELECT a.id,a.name,count(*) OVER() AS total
FROM application a
WHERE a.workspace_id=$1::uuid
 AND ($2::uuid IS NULL OR a.project_id=$2::uuid)
 AND (
  EXISTS(SELECT 1 FROM application_instance i WHERE i.workspace_id=a.workspace_id
   AND (i.application_id=a.id OR EXISTS(SELECT 1 FROM application_instance_consumer c
     WHERE c.workspace_id=i.workspace_id AND c.instance_id=i.id AND c.root_application_id=a.id
       AND ($3::uuid IS NULL OR i.runtime_id=$3::uuid OR c.root_runtime_id=$3::uuid)))
   AND ($3::uuid IS NULL OR i.runtime_id=$3::uuid
     OR EXISTS(SELECT 1 FROM application_instance_consumer c WHERE c.workspace_id=i.workspace_id AND c.instance_id=i.id AND c.root_application_id=a.id AND c.root_runtime_id=$3::uuid))
   AND (i.desired_state='running' OR i.process_state NOT IN ('stopped','failed') OR i.generation<>i.observed_generation))
  OR EXISTS(SELECT 1 FROM application_operation o WHERE o.workspace_id=a.workspace_id AND o.application_id=a.id
   AND o.state IN ('queued','running','cancelling') AND ($3::uuid IS NULL OR o.plan->>'root_runtime_id'=$3::text
     OR EXISTS(SELECT 1 FROM application_operation_step s WHERE s.workspace_id=o.workspace_id AND s.operation_id=o.id AND s.runtime_id=$3::uuid AND s.state IN ('queued','running'))))
 )
ORDER BY a.id LIMIT 10
`

